import java.util.Scanner;
public class JInput3 {
	public static void main(String[] args) {
		//Khatwa 1: Iqra' al-awwal raqam alladhi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil raqam:");
		int num = scan.nextInt();
		//Khatwa 2: Taba' al-raqam alladhi adkhalahu al-mustakhdim, thumma istaqbil al-arqam al-muqbila ma damaa al-mustakhdim yadkhul raqam ghayr salib wa la yazid 1000; wa fi ghayr dhalik tawqaf
		while ( num >= 0 && num <= 1000 ) {
			System.out.println("Al-raqam al-mudkhal huwa " + num);
			System.out.println("Adkhil raqam:");
			num = scan.nextInt(); 
		}
		scan.close();
		System.out.println("Nihayat al-dakhl.");
	}
}
